def transforms(sh):
 out=[]
 for refl in [False,True]:
  for rot in range(4):
   pts=[(r,c*(-1 if refl else 1)) for r,c in sh]
   for _ in range(rot): pts=[(c,-r) for r,c in pts]
   mr=min(r for r,c in pts); mc=min(c for r,c in pts)
   norm=tuple(sorted((r-mr,c-mc) for r,c in pts))
   if norm not in out: out.append(norm)
 return out
def pred_matches(grid,sh):
 hits=[]
 for shp in transforms(sh):
  H=max(r for r,c in shp)+1; W=max(c for r,c in shp)+1
  for r in range(len(grid)-H+1):
   for c in range(len(grid[0])-W+1):
    if all(grid[r+dr][c+dc]==0 for dr,dc in shp): hits.append((shp,r,c))
 return hits
def coverage(grid,sh):
 cov=set()
 for shp,r,c in pred_matches(grid,sh): cov|={(r+dr,c+dc) for dr,dc in shp}
 return cov
